"""Rebuild the runtime PDF resource script from the included PDF.js data."""
import base64
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
source = root / 'vendor-source/pdfjs'
resources = {
    kind: {p.name: base64.b64encode(p.read_bytes()).decode('ascii')
           for p in sorted((source / folder).iterdir())
           if p.suffix in ('.bcmap', '.ttf', '.pfb')}
    for kind, folder in [('cmaps', 'cmaps'), ('fonts', 'standard_fonts')]
}
(root / 'site/vendor/pdf-resources.js').write_text(
    '// PDF.js 3.11.174 static assets, Apache-2.0. Generated by tests/build_pdf_resources.py\n'
    'window.PDF_LOCAL_RESOURCES=' + json.dumps(resources, separators=(',', ':')) + ';\n',
    encoding='utf-8',
)
